    R"GLSL(#version 330 core
out vec4 soulFragColor;
  in vec3  vColor;
  in float vAlpha;
  void main() {
    vec2 c = gl_PointCoord - 0.5;
    float d2 = dot(c, c) * 4.0;
    if (d2 > 1.0) discard;
    soulFragColor = vec4(vColor, exp(-d2 * 3.0) * (1.0 - d2) * vAlpha);
  }
)GLSL";

